def _to_decimal(value):
    """Convert a numeric input to a Decimal using string conversion.

    Booleans are never valid money values.
    """
    if isinstance(value, bool):
        raise ValueError("price and quantity must not be booleans")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, str):
        # Validate the string is numeric before converting, so non-numeric
        # strings raise ValueError rather than InvalidOperation.
        try:
            return Decimal(value)
        except InvalidOperation:
            raise ValueError("invalid numeric value")
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, float):
        return Decimal(str(value))
    raise ValueError("unsupported numeric type")


def line_total(price, quantity, discount_percent=0):
    price = _to_decimal(price)
    quantity = _to_decimal(quantity)
    discount_percent = _to_decimal(discount_percent)

    # Reject negative / nonfinite price and non-integer / negative quantity.
    if price < 0 or price != price or price.is_infinite():  # NaN check: NaN < 0 is False, so use is_nan
        raise ValueError("price must be a finite, nonnegative number")
    if quantity < 0 or quantity != quantity or quantity.is_nan() or not quantity.is_integer():
        raise ValueError("quantity must be a nonnegative integer")
    if discount_percent < 0 or discount_percent > 100 or discount_percent.is_nan() or discount_percent.is_infinite():
        raise ValueError("discount_percent must be in 0..100")

    # Apply discount before rounding, then round HALF_UP to two places.
    return (price * quantity * (Decimal(1) - discount_percent / Decimal(100))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
